function yocnReq(int$p,string$m,string$path,array$form,array&$cookies):array{$b=$form===[]?'':http_build_query($form);$h=['Host: fmonitor.example.test','Connection: close'];if($cookies)$h[]='Cookie: '.implode('; ',array_map(static fn($k,$v)=>"$k=$v",array_keys($cookies),$cookies));if($b!=='')$h[]='Content-Type: application/x-www-form-urlencoded';$c=stream_context_create(['http'=>['ignore_errors'=>true,'follow_location'=>0,'method'=>$m,'header'=>implode("\r\n",$h),'content'=>$b]]);$body=file_get_contents("http://127.0.0.1:$p$path",false,$c);$raw=$http_response_header??[];$headers=[];foreach(array_slice($raw,1)as$l){$at=strpos($l,':');if($at!==false)$headers[strtolower(substr($l,0,$at))]=trim(substr($l,$at+1));}if(isset($headers['set-cookie'])&&preg_match('/^([^=;]+)=([^;]*)/',$headers['set-cookie'],$x))$cookies[$x[1]]=$x[2];preg_match('#^HTTP/\S+ (\d+)#',$raw[0]??'',$x);return[(int)($x[1]??0),$headers,(string)$body];}function yocnCsrf(string$h):string{preg_match('/name="_csrf" value="([^"]+)"/',$h,$m);return html_entity_decode($m[1]??throw new TestFailure('SETUP_FAILURE csrf'),ENT_QUOTES|ENT_HTML5);}
