$calc=yocnParallel($port,'/pilot/otiz/calculate',['_csrf'=>$csrf,'reportDate'=>'2026-09-08','operationId'=>'70000000-0000-4000-8000-000000000002'],$cookies);assertSameValue($calc[0],$calc[1],'concurrent calculate returns same result');assertSameValue(303,$calc[0][0],'concurrent calculate redirects');preg_match('#/snapshots/(\d+)#',$calc[0][1]??'',$m);$id=(int)($m[1]??0);assertSameValue([1,1,1],[(int)$db->query("SELECT COUNT(*) FROM `{$p}fm2_pilot_otiz_snapshots`")->fetch_column(),(int)$db->query("SELECT COUNT(*) FROM `{$p}fm2_otiz_publications`")->fetch_column(),(int)$db->query("SELECT COUNT(*) FROM `{$p}fm2_pilot_otiz_events` WHERE event_type='draft_calculated'")->fetch_column()],'concurrent publication has one fact set');$accept=yocnParallel($port,"/pilot/otiz/snapshots/$id/accept",['_csrf'=>$csrf],$cookies);sort($accept);assertSameValue([303,303],array_column($accept,0),'concurrent accept maps both requests');assertSameValue(1,(int)$db->query("SELECT COUNT(*) FROM `{$p}fm2_pilot_otiz_events` WHERE event_type='snapshot_accepted'")->fetch_column(),'concurrent accept has one event');echo "PASS: YII2-OTIZ-WORKFLOW-001 HTTP concurrency and rollback\n";}finally{if(is_resource($server)){proc_terminate($server);proc_close($server);}$f->close();}
